+    constexpr int TILE_SIZE = 32; // Block size, chosen to fit L1/L2 cache well
+    for (int ii = 0; ii < n; ii += TILE_SIZE) {
+        for (int jj = 0; jj < n; jj += TILE_SIZE) {
+            // Load C tile into registers/cache block (C_tile)
+            // This is conceptually complex for a simple loop structure,
+            // so we compute C[i][j] directly using the block structure to maximize locality.
+            for (int i = ii; i < std::min(ii + TILE_SIZE, n); ++i) {
+                for (int j = jj; j < std::min(jj + TILE_SIZE, n); ++j) {
